def recibo_da_compra(nomes, precos, comprados):
    linhas = []
    total = 0
    for nome, preco, quantidade in zip(nomes, precos, comprados):
        subtotal = preco * quantidade
        total += subtotal
        linhas.append(f"{nome} x{quantidade} = {round(subtotal, 2)}")
    linhas.append(f"total = {round(total, 2)}")
    return linhas


def par_do_mais_caro(nomes, precos):
    mais_caro = max(precos)
    return (nomes[precos.index(mais_caro)], mais_caro)


def quem_falta(estoque, pedidos):
    faltas = []
    for item in pedidos:
        if item in estoque:
            continue
        faltas.append(item)
    return faltas
